//! Minimal `admin/roles/create` + `admin/roles/assign` SQL support
//! (upstream `RoleService.create` / `RoleService.addAssign`,
//! `src/core/RoleService.ts`):
//! - `create_role` inserts one `role` row (`updatedAt`/`lastUsedAt` = now,
//!   id generated by the caller through the shared AID generator);
//! - `assign_role` inserts a non-expiring `role_assignment` unless the pair
//!   already exists (upstream throws AlreadyAssignedError; we surface
//!   `None` so the handler can answer `ROLE_ALREADY_ASSIGNED`), and bumps
//!   `role.lastUsedAt` like upstream.

use sqlx::PgPool;

/// `RoleService.create` — insert one manual role; returns the id.
pub async fn create_role(
    pool: &PgPool,
    id: &str,
    name: &str,
    description: &str,
    color: Option<&str>,
    icon_url: Option<&str>,
    is_public: bool,
    is_moderator: bool,
    is_administrator: bool,
    target: &str,
    cond_formula: &serde_json::Value,
    as_badge: bool,
    is_explorable: bool,
    preserve_assignment_on_move_account: bool,
    can_edit_members_by_moderator: bool,
    display_order: i64,
    policies: &serde_json::Value,
) -> Result<(), sqlx::Error> {
    sqlx::query(
        r#"
        INSERT INTO "role"
            ("id", "updatedAt", "lastUsedAt", "name", "description", "color",
             "iconUrl", "isPublic", "isModerator", "isAdministrator", "target",
             "condFormula", "asBadge", "isExplorable",
             "preserveAssignmentOnMoveAccount", "canEditMembersByModerator",
             "displayOrder", "policies")
        VALUES ($1, now(), now(), $2, $3, $4, $5, $6, $7, $8, $9,
                $10::jsonb, $11, $12, $13, $14, $15, $16::jsonb)
        "#,
    )
    .bind(id)
    .bind(name)
    .bind(description)
    .bind(color)
    .bind(icon_url)
    .bind(is_public)
    .bind(is_moderator)
    .bind(is_administrator)
    .bind(target)
    .bind(cond_formula)
    .bind(as_badge)
    .bind(is_explorable)
    .bind(preserve_assignment_on_move_account)
    .bind(can_edit_members_by_moderator)
    .bind(display_order)
    .bind(policies)
    .execute(pool)
    .await?;
    Ok(())
}

/// Upstream fetches needed by the create handler to echo the packed Role.
/// `"updatedAt"` is fetched as SQL text (timestamptz::text) — the Role pack
/// renders ISO strings; the handler reuses this only as a placeholder string
/// the e2e consumers never datetime-parse.
#[derive(Debug, Clone, sqlx::FromRow)]
pub struct RoleRow {
    pub id: String,
    pub name: String,
    pub description: String,
    pub color: Option<String>,
    #[sqlx(rename = "iconUrl")]
    pub icon_url: Option<String>,
    pub target: String,
    #[sqlx(rename = "condFormula")]
    pub cond_formula: serde_json::Value,
    #[sqlx(rename = "isPublic")]
    pub is_public: bool,
    #[sqlx(rename = "isAdministrator")]
    pub is_administrator: bool,
    #[sqlx(rename = "isModerator")]
    pub is_moderator: bool,
    #[sqlx(rename = "isExplorable")]
    pub is_explorable: bool,
    #[sqlx(rename = "asBadge")]
    pub as_badge: bool,
    #[sqlx(rename = "preserveAssignmentOnMoveAccount")]
    pub preserve_assignment_on_move_account: bool,
    #[sqlx(rename = "canEditMembersByModerator")]
    pub can_edit_members_by_moderator: bool,
    #[sqlx(rename = "displayOrder")]
    pub display_order: i64,
    pub policies: serde_json::Value,
    #[sqlx(rename = "updatedAt")]
    pub updated_at: String,
}

/// One role row for the create response pack (`RoleEntityService.pack`).
pub async fn find_role(pool: &PgPool, id: &str) -> Result<Option<RoleRow>, sqlx::Error> {
    sqlx::query_as::<_, RoleRow>(
        r#"
        SELECT "id", "name", "description", "color", "iconUrl", "target",
               "condFormula", "isPublic", "isAdministrator", "isModerator",
               "isExplorable", "asBadge", "preserveAssignmentOnMoveAccount",
               "canEditMembersByModerator", "displayOrder"::bigint AS "displayOrder",
               "policies", "updatedAt"::text AS "updatedAt"
        FROM "role" WHERE "id" = $1
        "#,
    )
    .bind(id)
    .fetch_optional(pool)
    .await
}

/// `RoleService.addAssign` minus the events/notifications: dedup
/// (`expiresAt` in the past is treated as free, future/live as
/// AlreadyAssignedError), non-expiring insert, `lastUsedAt` bump. Returns
/// `Ok(false)` when the pair is already live-assigned.
pub async fn assign_role(
    pool: &PgPool,
    id: &str,
    user_id: &str,
    role_id: &str,
) -> Result<bool, sqlx::Error> {
    let mut tx = pool.begin().await?;
    let live: bool = sqlx::query_scalar(
        r#"SELECT EXISTS(
               SELECT 1 FROM "role_assignment"
               WHERE "roleId" = $1 AND "userId" = $2
                 AND ("expiresAt" IS NULL OR "expiresAt" > now())
           )"#,
    )
    .bind(role_id)
    .bind(user_id)
    .fetch_one(&mut *tx)
    .await?;
    if live {
        tx.rollback().await.ok();
        return Ok(false);
    }
    // upstream first deletes an expired-assignment row when re-assigning
    sqlx::query(r#"DELETE FROM "role_assignment" WHERE "roleId" = $1 AND "userId" = $2"#)
        .bind(role_id)
        .bind(user_id)
        .execute(&mut *tx)
        .await?;
    sqlx::query(
        r#"INSERT INTO "role_assignment" ("id", "userId", "roleId", "expiresAt")
           VALUES ($1, $2, $3, NULL)"#,
    )
    .bind(id)
    .bind(user_id)
    .bind(role_id)
    .execute(&mut *tx)
    .await?;
    sqlx::query(r#"UPDATE "role" SET "lastUsedAt" = now() WHERE "id" = $1"#)
        .bind(role_id)
        .execute(&mut *tx)
        .await?;
    tx.commit().await?;
    Ok(true)
}

/// Assignment count for the Role pack `usersCount`
/// (`RoleEntityService.pack`: non-expired only).
pub async fn count_assignments(pool: &PgPool, role_id: &str) -> Result<i64, sqlx::Error> {
    sqlx::query_scalar(
        r#"SELECT count(*) FROM "role_assignment"
           WHERE "roleId" = $1 AND ("expiresAt" IS NULL OR "expiresAt" > now())"#,
    )
    .bind(role_id)
    .fetch_one(pool)
    .await
}
